+constexpr int KDA_CHUNK_SIZE = 64;
+inline float sigmoid_fp32(float x) {
+  if (x >= 0.f) {
+    float z = std::exp(-x);
+    return 1.f / (1.f + z);
+  }
+  float z = std::exp(x);
+  return z / (1.f + z);
+}
+
+inline float softplus_fp32(float x) {
+  if (x > 20.f) {
+    return x;
+  }
+  if (x < -20.f) {
+    return std::exp(x);
+  }
+  return std::log1p(std::exp(x));
+}
